CREATE FUNCTION hiring_private.hiring_rating_flags_step4() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE flags jsonb; reviewer uuid; BEGIN IF OLD.is_draft AND NOT NEW.is_draft THEN SELECT coalesce(jsonb_agg(jsonb_build_object('question_id',q.id,'rule',coalesce(q.knockout_rule,b.knockout_rule),'answer',a.answer)),'[]') INTO flags FROM public.job_questions q JOIN public.application_answers a ON a.job_question_id=q.id AND a.application_id=NEW.id LEFT JOIN public.question_bank b ON b.id=q.question_id WHERE q.job_id=NEW.job_id AND q.type='rating' AND jsonb_typeof(a.answer)='number' AND coalesce(q.knockout_rule,b.knockout_rule) ? 'less_than' AND (a.answer#>>'{}')::numeric < (coalesce(q.knockout_rule,b.knockout_rule)->>'less_than')::numeric;
IF flags<>'[]'::jsonb THEN SELECT user_id INTO reviewer FROM public.hiring_user_roles WHERE role='admin' ORDER BY created_at LIMIT 1; IF reviewer IS NULL THEN RAISE EXCEPTION 'Hiring admin must be configured'; END IF; INSERT INTO public.application_reviews(application_id,reviewer_id,knockout_flags) VALUES(NEW.id,reviewer,flags) ON CONFLICT(application_id,reviewer_id) DO UPDATE SET knockout_flags=public.application_reviews.knockout_flags||excluded.knockout_flags; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION hiring_private.hiring_rating_flags_step4() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER hiring_rating_flags_step4 AFTER UPDATE OF is_draft ON public.applications FOR EACH ROW EXECUTE FUNCTION hiring_private.hiring_rating_flags_step4();